import useLike from '../hooks/useLike.js';
import useRetweet from '../hooks/useRetweet.js';
import TweetActions from './TweetActions.jsx';
import { mockTweet } from '../data/mockTweet.js';

function Tweet({ tweet = mockTweet }) {
  const { liked, likeCount, toggleLike } = useLike(tweet.isLiked, tweet.likeCount);
  const { retweeted, retweetCount, toggleRetweet } = useRetweet(
    tweet.isRetweeted,
    tweet.retweetCount
  );

  return (
    <article className="tweet" data-testid="tweet-card">
      <div className="tweet-author">
        <span className="avatar" aria-hidden="true">
          {tweet.author.name.charAt(0)}
        </span>
        <span className="author-name" data-testid="tweet-author-name">
          {tweet.author.name}
        </span>
        <span className="author-handle" data-testid="tweet-author-handle">
          {tweet.author.handle}
        </span>
      </div>
      <p className="tweet-content" data-testid="tweet-content">
        {tweet.content}
      </p>
      <time className="tweet-time" data-testid="tweet-time">
        {new Date(tweet.createdAt).toLocaleDateString()}
      </time>
      <TweetActions
        replyCount={tweet.replyCount}
        retweetCount={retweetCount}
        retweeted={retweeted}
        likeCount={likeCount}
        liked={liked}
        onLike={toggleLike}
        onRetweet={toggleRetweet}
      />
    </article>
  );
}

export default Tweet;

