function TweetActions({
  replyCount,
  retweetCount,
  retweeted,
  likeCount,
  liked,
  onLike,
  onRetweet,
}) {
  return (
    <div className="tweet-actions" data-testid="tweet-actions">
      <button type="button" className="action reply" data-testid="reply-button">
        <span className="action-label">Reply</span>
        <span className="count" data-testid="reply-count">
          {replyCount}
        </span>
      </button>

      <button
        type="button"
        className={`action retweet${retweeted ? ' is-active' : ''}`}
        aria-pressed={retweeted}
        data-testid="retweet-button"
        onClick={onRetweet}
      >
        <span className="action-label">Retweet</span>
        <span className="count" data-testid="retweet-count">
          {retweetCount}
        </span>
      </button>

      <button
        type="button"
        className={`action like${liked ? ' is-active' : ''}`}
        aria-pressed={liked}
        data-testid="like-button"
        onClick={onLike}
      >
        <span className="action-label">Like</span>
        <span className="count" data-testid="like-count">
          {likeCount}
        </span>
      </button>
    </div>
  );
}

export default TweetActions;

