import { useState } from 'react';

export default function useRetweet(initialRetweeted = false, initialCount = 0) {
  const [retweeted, setRetweeted] = useState(initialRetweeted);
  const [retweetCount, setRetweetCount] = useState(initialCount);

  // BUG: the retweet count does not return to its previous value when a
  // retweet is undone. QA watched the counter drift downward as it was
  // toggled on and off. Find and fix the arithmetic here.
  function toggleRetweet() {
    if (retweeted) {
      setRetweeted(false);
      setRetweetCount(retweetCount - 2);
    } else {
      setRetweeted(true);
      setRetweetCount(retweetCount + 1);
    }
  }

  return { retweeted, retweetCount, toggleRetweet };
}

