import { describe, test, expect } from 'vitest';
import { render, fireEvent } from '@testing-library/react';
import '@testing-library/jest-dom';
import React from 'react';
import App from '../src/App.jsx';
import Tweet from '../src/components/Tweet.jsx';

const zeroTweet = {
  id: 'tweet-000',
  author: {
    name: 'Zero User',
    handle: '@zero_user',
  },
  content: 'Starting from nothing.',
  createdAt: '2026-01-01T00:00:00.000Z',
  replyCount: 3,
  retweetCount: 0,
  likeCount: 0,
  isLiked: false,
  isRetweeted: false,
};

const countAt = (container, id) => {
  const el = container.querySelector(`[data-testid="${id}"]`);
  return el ? el.textContent.trim() : null;
};

const pressed = (container, id) =>
  container.querySelector(`[data-testid="${id}"]`).getAttribute('aria-pressed');

const isActive = (container, id) =>
  container.querySelector(`[data-testid="${id}"]`).classList.contains('is-active');

describe('Tweet component', () => {
  test('renders the tweet author, content, and initial counts', () => {
    const { container } = render(<App />);
    const author = container.querySelector('[data-testid="tweet-author-name"]');
    if (!author || !author.textContent.includes('Ada Lovelace')) {
      throw new Error('Tweet should show the author name "Ada Lovelace"');
    }
    const handle = container.querySelector('[data-testid="tweet-author-handle"]');
    if (!handle || !handle.textContent.includes('@ada_loves_code')) {
      throw new Error('Tweet should show the author handle "@ada_loves_code"');
    }
    const content = container.querySelector('[data-testid="tweet-content"]');
    if (!content || !content.textContent.includes('Analytical Engine')) {
      throw new Error('Tweet should show the tweet content');
    }
    if (countAt(container, 'reply-count') !== '12') {
      throw new Error('Reply count should start at 12');
    }
    if (countAt(container, 'retweet-count') !== '34') {
      throw new Error('Retweet count should start at 34');
    }
    if (countAt(container, 'like-count') !== '156') {
      throw new Error('Like count should start at 156');
    }
  });

  test('clicking like increments the count and marks it liked', () => {
    const { container } = render(<App />);
    const likeButton = container.querySelector('[data-testid="like-button"]');
    fireEvent.click(likeButton);
    if (countAt(container, 'like-count') !== '157') {
      throw new Error(`Expected like count 157 after liking, got ${countAt(container, 'like-count')}`);
    }
    if (pressed(container, 'like-button') !== 'true') {
      throw new Error('Like button should have aria-pressed="true" after liking');
    }
    if (!isActive(container, 'like-button')) {
      throw new Error('Like button should get the "is-active" class when liked');
    }
  });

  test('clicking like again un-likes and decrements back', () => {
    const { container } = render(<App />);
    const likeButton = container.querySelector('[data-testid="like-button"]');
    fireEvent.click(likeButton);
    fireEvent.click(likeButton);
    if (countAt(container, 'like-count') !== '156') {
      throw new Error(`Expected like count back to 156, got ${countAt(container, 'like-count')}`);
    }
    if (pressed(container, 'like-button') !== 'false') {
      throw new Error('Like button should have aria-pressed="false" after un-liking');
    }
    if (isActive(container, 'like-button')) {
      throw new Error('Like button should not keep the "is-active" class after un-liking');
    }
  });

  test('clicking retweet toggles the retweet state and count correctly', () => {
    const { container } = render(<App />);
    const retweetButton = container.querySelector('[data-testid="retweet-button"]');
    fireEvent.click(retweetButton);
    if (countAt(container, 'retweet-count') !== '35') {
      throw new Error(
        `Expected retweet count 35 after retweeting, got ${countAt(container, 'retweet-count')}`
      );
    }
    if (pressed(container, 'retweet-button') !== 'true') {
      throw new Error('Retweet button should have aria-pressed="true" after retweeting');
    }
    fireEvent.click(retweetButton);
    if (countAt(container, 'retweet-count') !== '34') {
      throw new Error(
        `Expected retweet count to return to 34, got ${countAt(container, 'retweet-count')}`
      );
    }
    if (pressed(container, 'retweet-button') !== 'false') {
      throw new Error('Retweet button should have aria-pressed="false" after un-retweeting');
    }
  });

  test('counts never go negative when toggling from zero', () => {
    const { container } = render(<Tweet tweet={zeroTweet} />);
    const likeButton = container.querySelector('[data-testid="like-button"]');
    const retweetButton = container.querySelector('[data-testid="retweet-button"]');

    fireEvent.click(likeButton);
    if (countAt(container, 'like-count') !== '1') {
      throw new Error('Like count should reach 1 on a zero-count tweet');
    }
    fireEvent.click(likeButton);
    if (countAt(container, 'like-count') !== '0') {
      throw new Error(
        `Like count must never go negative; expected 0, got ${countAt(container, 'like-count')}`
      );
    }

    fireEvent.click(retweetButton);
    if (countAt(container, 'retweet-count') !== '1') {
      throw new Error('Retweet count should reach 1 on a zero-count tweet');
    }
    fireEvent.click(retweetButton);
    if (countAt(container, 'retweet-count') !== '0') {
      throw new Error(
        `Retweet count must never go negative; expected 0, got ${countAt(container, 'retweet-count')}`
      );
    }
  });

  test('aria-pressed and is-active reflect the current liked/retweeted state', () => {
    const { container } = render(<App />);
    const likeButton = container.querySelector('[data-testid="like-button"]');
    const retweetButton = container.querySelector('[data-testid="retweet-button"]');

    fireEvent.click(likeButton);
    fireEvent.click(retweetButton);

    if (pressed(container, 'like-button') !== 'true' || !isActive(container, 'like-button')) {
      throw new Error('Like button should show an active liked state');
    }
    if (
      pressed(container, 'retweet-button') !== 'true' ||
      !isActive(container, 'retweet-button')
    ) {
      throw new Error('Retweet button should show an active retweeted state');
    }

    fireEvent.click(likeButton);

    if (pressed(container, 'like-button') !== 'false' || isActive(container, 'like-button')) {
      throw new Error('Like button should clear its active state when un-liked');
    }
    if (pressed(container, 'retweet-button') !== 'true') {
      throw new Error('Un-liking must not affect the retweet state');
    }
  });
});
